import json
from pathlib import Path
R=Path.cwd();O=R/'outputs/expanded/key_moments';cases=[]
for c,t in [(c,t) for c in 'EFGH' for t in [4,8,12,16]]+[('B',t) for t in [4,6,7]]:
 p=O/'references'/f'{c}_{t}.json'
 if not p.exists():continue
 preds={k:json.load(open(O/'predictions'/f'{c}_{t}_{k}.json')) for k in ['phase_recent_events','rich_history','rich_pose_history'] if(O/'predictions'/f'{c}_{t}_{k}.json').exists()}
 cases.append({'clip':c,'cutoff':t,'reference':json.load(open(p)),'past':json.load(open(O/'prefixes'/f'{c}_{t}.json')),'predictions':preds})
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MMA / Key-moment foresight</title><style>
:root{--bg:#10171c;--panel:#18232a;--ink:#edf0e9;--muted:#a3b0b7;--cyan:#22d3ee;--coral:#fb7185}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui}main{max-width:1300px;margin:auto;padding:32px}a{color:var(--cyan)}h1{font-size:clamp(36px,5vw,62px);letter-spacing:-2px;font-weight:550;line-height:1.12;max-width:850px}p{color:var(--muted)}.kicker{font-size:12px;letter-spacing:2px;color:var(--cyan)}.grid{display:grid;grid-template-columns:1.1fr 1fr;gap:22px}.card{background:var(--panel);padding:20px;border:1px solid #35434a;border-radius:12px}video{width:100%;background:black;aspect-ratio:16/9}button,select{font:inherit;background:#1c2a33;color:var(--ink);border:1px solid #485e69;border-radius:5px;padding:9px;margin:0 6px 12px 0;cursor:pointer}.bar{margin:20px 0}.barhead{display:flex;justify-content:space-between;gap:14px}.track{height:10px;background:#30414a;position:relative;margin:9px 0}.track:after{content:'';position:absolute;left:50%;top:0;height:100%;width:1px;background:#97a6ad}.fill{height:100%;background:var(--cyan)}.reason{font-size:13px;color:var(--muted)}.truth{margin-top:12px;border-left:2px solid var(--coral);padding:12px;background:#251f28}.note{border-left:2px solid var(--coral);padding:12px 18px;background:#1b252b;margin:24px 0}.comparison{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--muted)}.comparison span{border:1px solid #3d4c54;padding:5px 7px;border-radius:4px}pre{font:12px/1.5 monospace;white-space:pre-wrap;overflow-wrap:anywhere}details{margin:15px 0}summary{cursor:pointer;color:var(--cyan)}.status{color:var(--cyan);font:13px monospace}.curve{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.curve div{border:1px solid #3d4c54;padding:12px;border-radius:6px}.curve strong{font-size:25px;display:block}.small{font-size:12px;color:var(--muted)}table{border-collapse:collapse;font-size:13px;width:100%}td,th{text-align:left;padding:9px;border-bottom:1px solid #36464e}@media(max-width:850px){.grid{grid-template-columns:1fr}main{padding:18px}}
</style></head><body><main><a href="../index.html">← Evidence laboratory</a><div class="kicker">CAUSAL SEQUENCES / MEANINGFUL EVENTS / NO TRAINING</div><h1>What starts in the next four seconds?</h1><p>Strikes, takedown attempts, submission entries, and major control changes. Each can happen in the same window, so their probabilities are separate. Freeze the fight at a cutoff, inspect the forecast, then reveal the next exchange.</p><select id="case" aria-label="Choose prediction window"></select><select id="cond" aria-label="Prediction data"><option value="phase_recent_events">Phase + recent events</option><option value="rich_history" selected>Rich annotation history</option><option value="rich_pose_history">Rich history + pose candidates</option></select><div class="grid"><section class="card"><video id="v" controls muted playsinline preload="metadata"></video><div class="status" id="status"></div><button id="past">Watch observed prefix</button><button id="freeze">Freeze at cutoff</button><button id="reveal">Reveal next four seconds</button><div id="reference" hidden></div><details><summary>Exactly what the predictor was told</summary><pre id="prefix"></pre></details></section><section class="card"><div id="bars"></div><p class="small">The line marks the preselected 50% alert threshold. These experimental probabilities are not calibrated fight-wide risk estimates.</p><details><summary>Prediction rationale and uncertainty</summary><pre id="raw"></pre></details></section></div><section class="card" style="margin-top:22px"><h2>One takedown. Three warning distances.</h2><p>Clip B is a deliberately selected stress test of a previously missed entry. Cutoffs 4, 6, and 7 seconds look toward the same episode; they are not three independent successful or failed takedowns.</p><div class="curve" id="curve"></div><p class="small">Values shown are next-four-second takedown probabilities from the selected input condition. Reference onset times are approximate; warnings after commitment do not count as anticipation.</p></section><div class="note">Separate Sol image reviews provide the reference labels. Unclear targets remain unscored. Ordinary cases come from three bouts, with correlated nearby windows. The takedown stress test was selected after observing a failure. This experiment tests promising directions; it does not establish general forecasting accuracy.</div><p><a href="subtypes/index.html">Separate punch, kick, clinch, ground and submission results ↗</a> · <a href="reference_changes.json">Native review disagreements ↗</a> · <a href="dense_prefix/case_scores.json">Dense causal-prefix test ↗</a></p><h2>Probability error by target</h2><p>Binary Brier error: lower is better. Compare ordinary windows against always predicting no event; inspect the selected takedown episode separately.</p><div id="scores"></div><p><a href="protocol.json">Protocol</a> · <a href="scores.json">Full scores</a> · <a href="case_scores.json">Every scored probability</a> · <a href="frozen_references.json">Frozen reference hashes</a></p></main><script>
const DATA=__DATA__,SCORES=__SCORES__,$=x=>document.getElementById(x),v=$('v'),NAMES={strike_attempt:'Strike attempt',takedown_attempt:'Takedown attempt',submission_entry:'Submission entry',major_control_transition:'Major control change'};let stop=4,revealed=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function d(){return DATA[Number($('case').value)]}function render(){v.pause();let x=d(),c=$('cond').value,p=x.predictions[c];v.src=x.clip==='B'?'../../experiment/clips/B.mp4':'../clips/'+x.clip+'.mp4';stop=x.cutoff;v.currentTime=Math.max(0,x.cutoff-.2);revealed=false;$('reference').hidden=true;$('status').textContent='Observed through '+x.cutoff+'s · predict ['+x.cutoff+', '+(x.cutoff+4)+')';$('prefix').textContent=JSON.stringify(x.past,null,2);$('raw').textContent=JSON.stringify(p||{status:'prediction incomplete'},null,2);$('bars').innerHTML=Object.entries(NAMES).map(([k,n])=>{let q=p?.probabilities?.[k];return `<div class="bar"><div class="barhead"><strong>${n}</strong><strong>${q===undefined?'pending':(100*q).toFixed(0)+'%'}</strong></div><div class="track"><div class="fill" style="width:${100*(q||0)}%"></div></div><div class="comparison">${Object.entries(x.predictions).map(([co,pr])=>`<span>${co.replaceAll('_',' ')}: ${(100*pr.probabilities[k]).toFixed(0)}%</span>`).join('')}</div><div class="reason">${esc(p?.rationale_by_target?.[k]||'')}</div><div id="truth_${k}"></div></div>`}).join('');$('curve').innerHTML=DATA.filter(x=>x.clip==='B').map(x=>{let q=x.predictions[c]?.probabilities.takedown_attempt;return `<div><span>Cutoff ${x.cutoff}s</span><strong>${q===undefined?'pending':(q*100).toFixed(0)+'%'}</strong><span class="small">${(7.24-x.cutoff).toFixed(2)}–${(7.41-x.cutoff).toFixed(2)}s before reviewed entry interval</span></div>`}).join('')}
$('case').innerHTML=DATA.map((x,i)=>`<option value="${i}">Clip ${x.clip} · cutoff ${x.cutoff}s${x.clip==='B'?' · selected takedown test':''}</option>`).join('');$('case').onchange=render;$('cond').onchange=render;$('past').onclick=()=>{stop=d().cutoff;v.currentTime=0;v.play()};$('freeze').onclick=()=>{v.pause();v.currentTime=d().cutoff-.05;stop=d().cutoff};$('reveal').onclick=()=>{let x=d();revealed=true;stop=x.cutoff+4;v.currentTime=x.cutoff;$('reference').hidden=false;$('reference').innerHTML='<div class="truth"><strong>Independent future review</strong><p>Occurrences across the entire window; uncertain targets are not forced to no.</p></div>';for(let[k,r]of Object.entries(x.reference.targets))$('truth_'+k).innerHTML=`<div class="truth"><strong>${esc(r.occurrence)}</strong>${r.onsets_seconds.length?' · approximate onsets '+r.onsets_seconds.map(t=>Number(t).toFixed(2)+'s').join(', '):''}<p>${esc(r.evidence)}</p><div class="small">${esc(r.visibility_limits)}</div></div>`;v.play()};v.ontimeupdate=()=>{if(v.currentTime>=stop)v.pause()};const ordinary=SCORES.filter(r=>r.subset==='ordinary_registered');$('scores').innerHTML='<table><thead><tr><th>Input</th><th>Target</th><th>Scoreable</th><th>Positives</th><th>Brier ↓</th></tr></thead><tbody>'+ordinary.map(r=>`<tr><td>${r.condition.replaceAll('_',' ')}</td><td>${NAMES[r.target]}</td><td>${r.n}</td><td>${r.positives}</td><td>${r.mean_brier.toFixed(3)}</td></tr>`).join('')+'</tbody></table>';if(DATA.length)render();
</script></body></html>'''
scores=json.load(open(O/'scores.json')) if(O/'scores.json').exists() else []
(O/'index.html').write_text(html.replace('__DATA__',json.dumps(cases).replace('</','<\\/')).replace('__SCORES__',json.dumps(scores)))
print('KEY VIEWER',len(cases),'cases',sum(len(x['predictions']) for x in cases),'forecasts')
